/* questions.js: Dr. Lam, otic disorders (Lecture 13, taught 11/20), Exam 3. Earwax (cerumen) and water-clogged ear: collect, assess, plan,
   implement, follow up, the three-way differentiation (slide 23) and her practice cases (slides 36-44, not worked in class). Ids LOT-*.
   Sources: Lam_OticDisorders_slides.pdf (slide N = PDF page) and her handout Lam_OticDisorders_handout.pdf (p. N = handout page);
   DEENT_Lecture_11.20_transcript.txt (T@n = character offset, cited "11/20"; the otic part runs from 90689 to 101341).
   Conflicts (README): otic alcohol 95% in 5% anhydrous glycerin (slide, handout) vs "70%" (speech): no item keys the concentration;
   cerumen age (<12 on slide 10, "12 years and older" in the handout, "12 years or under" spoken): no scored item uses age 12;
   water-clogged follow-up ("several days" on slide 34 and the handout, "7 days" spoken): the scored case uses 7 days, the number item is lowYield;
   age for the alcohol drops (no minimum age on slide 31, age under 12 on the exclusion list, slide 26): lowYield. Slides 24-25 rows are lowYield
   (she called slide 23 the main slide). */
QUESTIONS.push(
{id:"LOT-001", skill:"patho", prof:'Lam', tier:'new', topic:"lt-cer", sub:"role", concept:"lot-role-multi", multi:true,
 tags:["list", "multi"], source:"both",
 stem:"Which of these are normal roles of earwax in the ear canal? Select all that apply.",
 options:[
  {t:"Lubricates the canal", correct:true, why:"Lubrication is a role she named for cerumen."},
  {t:"Dries moisture that is trapped in the canal", correct:false, why:"Drying is done by an alcohol drying agent or a water-absorbing earplug. Wax buildup is a cause of trapped moisture, not a remedy."},
  {t:"Traps foreign material before it reaches the eardrum", correct:true, why:"Trapping foreign objects is a role of cerumen; she used insects entering the ear as her example."},
  {t:"Conducts sound to the middle ear", correct:false, why:"She gave sound conduction as the function of the ear structure she was describing, not as a role of earwax."},
  {t:"Its acidic pH inhibits bacterial and fungal growth", correct:true, why:"Cerumen has an acidic pH and antimicrobial substances that inhibit bacterial and fungal growth."}],
 teach:"Earwax protects the canal: it lubricates, traps foreign material, forms a waterproof barrier against pathogens and is acidic enough to slow bacterial and fungal growth. Drying and sound conduction belong to other measures and structures, not to cerumen.",
 cite:"Lecture 13 (Lam_OticDisorders_slides.pdf) slides 7; handout p. 2; T@91166, T@91417, T@91744 11/20"},

{id:"LOT-002", skill:"epi", prof:'Lam', tier:'new', topic:"lt-cer", sub:"risk", concept:"lot-risk-habit",
 tags:["hard", "case"], source:"both",
 stem:"Mr. Foley, 55, cleans his ears every morning with cotton swabs and now has fullness and itching in both ears. Which statement links his habit to his symptoms?",
 options:[
  {t:"Swabs are an inappropriate removal method and a risk factor for impaction", correct:true, why:"Inappropriate methods of removing cerumen, such as cotton swabs, are a listed risk factor. He fits impaction, not a water-related problem."},
  {t:"Swabbing dries the canal, leaving too little moisture, and that causes the itching", correct:false, why:"Dryness from swabbing is not a point she made. Moisture retention is the cause of a water-clogged ear, which does not itch."},
  {t:"Swabbing wipes away the acidic wax, so a water-clogged ear then develops", correct:false, why:"A water-clogged ear is caused by retained moisture, hair, canal narrowing or debris. Itching and fullness here fit impaction."},
  {t:"Swabbing replaces the wet washcloth, so it is an accepted non-drug option", correct:false, why:"The accepted non-drug measure is a wet, wrung-out washcloth on the outer ear. A cotton swab is the method she called inappropriate."}],
 teach:"Pushing a swab into the canal is one of the habits that leads to impaction, so a patient with fullness and itching who swabs daily most likely has impacted cerumen. The safe daily option is a wet, wrung-out washcloth over a finger on the outer ear. Wipe the outer ear, not the inside.",
 cite:"Lecture 13 (Lam_OticDisorders_slides.pdf) slides 7; handout p. 2; T@91893 11/20"},

{id:"LOT-003", skill:"epi", prof:'Lam', tier:'new', topic:"lt-cer", sub:"risk", concept:"lot-risk-multi", multi:true,
 tags:["list", "multi"], source:"both",
 stem:"Which of these are risk factors for impacted cerumen? Select all that apply.",
 options:[
  {t:"Narrow or irregularly shaped ear canal", correct:true, why:"Canal shape is a listed risk factor for impaction."},
  {t:"Frequent swimming and high humidity", correct:false, why:"Swimming, sweating and humidity are causes of trapped water, so they point to a water-clogged ear rather than impaction."},
  {t:"Hearing aids or ear plugs irritating the canal", correct:true, why:"Irritation from foreign objects such as hearing aids or ear plugs is a listed risk factor."},
  {t:"Tympanostomy tubes", correct:false, why:"Tubes are an exclusion to self-care, not a risk factor for impacted cerumen."},
  {t:"Atrophy of the ceruminous glands in older adults", correct:true, why:"Gland atrophy in older adults is a listed risk factor."}],
 teach:"Risk factors for impaction involve anatomy (narrow or irregular canal, excess hair), irritation (hearing aids, swabs), aging glands and genetics. Swimming, sweating and humidity belong to water-clogged ears, and tubes are an exclusion.",
 cite:"Lecture 13 (Lam_OticDisorders_slides.pdf) slides 7; handout p. 2; T@91893 11/20"},

{id:"LOT-004", skill:"patho", prof:'Lam', tier:'new', topic:"lt-cer", sub:"risk", concept:"lot-child-flat",
 tags:["hard", "reasoning"], source:"both",
 stem:"A mother asks why her 4-year-old often has ear irritation when the child has a lot of nasal drainage. What explanation did Dr. Lam give?",
 options:[
  {t:"The child's canal glands are atrophied, so too little protective wax is made and the canal dries out", correct:false, why:"Gland atrophy is a risk factor in older adults. It does not explain a young child's ear problems with nasal drainage."},
  {t:"The child's canals are flat, so drainage backs up instead of draining down", correct:true, why:"In children the canal is flat; with growth it slants so fluid can drain downward. Nasal drainage therefore backs up in the ear."},
  {t:"The child's canals are acidic, so fungal growth is more likely when drainage collects", correct:false, why:"Cerumen has an acidic pH that prevents fungal and bacterial growth. Acidity does not explain the problem."},
  {t:"The child's canals have extra hair growth, which holds moisture and traps drainage in the canal", correct:false, why:"Excess hair growth is a cause of moisture retention in water-clogged ears. She did not use it for a child's drainage problem."}],
 teach:"In young children the ear canal is flat, and with growth it slants so that fluid drains downward. Nasal drainage that backs up there irritates or infects the ear. That anatomy is also why children under 12 are not treated with the OTC otic products.",
 cite:"Lecture 13 (Lam_OticDisorders_slides.pdf) slides 7, 10; handout p. 2; T@92189, T@92385 11/20"},

{id:"LOT-005", skill:"tell", prof:'Lam', tier:'new', topic:"lt-cer", sub:"pres", concept:"lot-pres-multi", multi:true,
 tags:["list", "multi"], source:"both",
 stem:"Which findings fit impacted cerumen? Select all that apply.",
 options:[
  {t:"Ear fullness or pressure", correct:true, why:"Fullness or pressure is a listed presentation."},
  {t:"Clear ear discharge with a swollen canal and fever", correct:false, why:"These findings point to swimmer's ear, an infection that needs a physician."},
  {t:"Ringing in the ear (tinnitus)", correct:true, why:"Tinnitus is listed; she explained it as ringing of the ears."},
  {t:"Abrupt hearing loss with brief, severe pain", correct:false, why:"This pattern fits a ruptured tympanic membrane and is an exclusion to self-care."},
  {t:"Itching in the ear", correct:true, why:"Itching is listed for cerumen and is a key difference from a water-clogged ear."}],
 teach:"Impaction produces fullness or pressure, dull pain, itching, discomfort, tinnitus, dizziness, vertigo, cough and hearing loss or hearing-aid feedback. Discharge with fever and a swollen canal points to infection, and abrupt loss with sharp pain points to a ruptured eardrum. Both go to a physician.",
 cite:"Lecture 13 (Lam_OticDisorders_slides.pdf) slides 8, 23, 24; T@92615 11/20"},

{id:"LOT-006", skill:"tell", prof:'Lam', tier:'new', topic:"lt-cer", sub:"excl", concept:"lot-excl-multi", multi:true,
 tags:["list", "multi"], source:"both",
 stem:"A patient with suspected impacted cerumen asks for an OTC ear product. Which findings exclude self-care? Select all that apply.",
 options:[
  {t:"Ear pain together with ear discharge", correct:true, why:"Pain with discharge looks like infection, which cannot be treated with an OTC product."},
  {t:"A sense of fullness in the ear", correct:false, why:"Fullness is part of the usual presentation and does not exclude self-care."},
  {t:"Ear surgery 3 weeks ago", correct:true, why:"Ear surgery within 6 weeks is an exclusion."},
  {t:"Itching in the ear", correct:false, why:"Itching is a usual presentation of impaction and does not exclude self-care."},
  {t:"Tympanostomy tubes in the ears", correct:true, why:"Tubes, or anything foreign, mean the patient is not treated with these products."}],
 teach:"Exclusions cover infection signs (discharge, rash, pain with discharge), bleeding or trauma, a ruptured eardrum, tubes, surgery within 6 weeks, age under 12, worsening after self-treatment and inability to follow instructions. Fullness and itching are the complaint itself, so those patients can be treated if nothing else is present.",
 cite:"Lecture 13 (Lam_OticDisorders_slides.pdf) slides 8, 10; handout p. 3; T@93008, T@93485 11/20"},

{id:"LOT-007", skill:"case", prof:'Lam', tier:'new', topic:"lt-cer", sub:"excl", concept:"lot-age-8",
 tags:["hard", "case"], source:"both",
 stem:"Four patients come to the pharmacy with ear fullness and itching and no other findings. Which one should be referred rather than offered an OTC product?",
 options:[
  {t:"A 34-year-old who cleans with cotton swabs", correct:false, why:"An adult with risk-factor behavior and no exclusion can be treated; the swabs should stop."},
  {t:"A 45-year-old with a long-standing narrow ear canal", correct:false, why:"A narrow canal is a risk factor, not an exclusion."},
  {t:"A 52-year-old with narrow ear canals", correct:false, why:"A narrow canal is a risk factor, not an exclusion."},
  {t:"An 8-year-old with a long cold", correct:true, why:"Children under 12 are an exclusion because the anatomy of their ears makes treatment difficult."}],
 teach:"Age under 12 is on the exclusion list because a child's canal anatomy makes treatment difficult. The other three patients each have a risk factor, which explains the symptoms but does not exclude them. The 8-year-old is referred to a doctor.",
 cite:"Lecture 13 (Lam_OticDisorders_slides.pdf) slides 10; handout p. 3; T@93276 11/20"},

{id:"LOT-008", skill:"case", prof:'Lam', tier:'new', topic:"lt-cer", sub:"excl", concept:"lot-infection-refer",
 tags:["hard", "case"], source:"both",
 stem:"Ms. Park, 40, has had ear fullness for 2 days and now notes ear discharge and irritation. She asks for Debrox. What should the pharmacist do?",
 options:[
  {t:"Recommend carbamide peroxide 6.5% twice daily for up to 4 days, then irrigation", correct:false, why:"Discharge and irritation suggest infection, and carbamide peroxide does not treat infection."},
  {t:"Recommend irrigation with warm sterile water and a bulb syringe", correct:false, why:"Irrigation is a non-drug option for impaction. It is not offered when signs of infection are present."},
  {t:"Refer her to a physician; this looks like an infection", correct:true, why:"Signs of infection or ear discharge exclude self-care; the infection needs a physician."},
  {t:"Recommend isopropyl alcohol drops, 4 to 5 drops, as a drying agent", correct:false, why:"Alcohol drops are for a water-clogged ear and are also excluded when discharge is present."}],
 teach:"Discharge or irritation means treat it as an infection, and pharmacists have nothing OTC for infection. She said if it looks like an infection, it probably is one. Any OTC product, including drops or irrigation, is the wrong move; the patient needs a physician.",
 cite:"Lecture 13 (Lam_OticDisorders_slides.pdf) slides 10; T@93008, T@93213 11/20"},

{id:"LOT-009", skill:"counsel", prof:'Lam', tier:'new', topic:"lt-cer", sub:"goal", concept:"lot-goal-cer",
 tags:["hard", "two-facts"], source:"both",
 stem:"Which pair states the treatment goals for impacted cerumen?",
 options:[
  {t:"Prevent recurrence of water retention and dry the canal with a safe, effective agent", correct:false, why:"These are the goals for a water-clogged ear, not for impaction."},
  {t:"Remove the cerumen and prevent potential adverse events", correct:true, why:"These are the stated goals: remove cerumen with safe, effective products and avoid harm."},
  {t:"Treat the infection and restore normal hearing in the affected ear canal", correct:false, why:"Infection cannot be treated with OTC products; it is a reason to refer."},
  {t:"Remove all earwax and stop the glands producing it so it cannot build up again", correct:false, why:"Earwax has protective roles, and the goal is to remove the excess, not all of it."}],
 teach:"The goal for impaction is removing the cerumen and avoiding harm, such as injury from deep tools. Drying the canal and preventing recurrence are goals for a water-clogged ear. Earwax is protective, so the aim is the excess, not every trace.",
 cite:"Lecture 13 (Lam_OticDisorders_slides.pdf) slides 11, 27; handout p. 3; T@93740 11/20"},

{id:"LOT-010", skill:"counsel", prof:'Lam', tier:'new', topic:"lt-cerrx", sub:"nonpharm", concept:"lot-washcloth",
 tags:["hard", "case"], source:"both",
 stem:"Ms. Greene, 61, wants a non-drug way to keep wax from building up at the outer ear. Which measure is described?",
 options:[
  {t:"An ear candle placed at the ear opening and burned slowly once a week for several weeks", correct:false, why:"Ear candles are not recommended because of potential danger and injury and no scientific evidence."},
  {t:"A damp washcloth over a finger, used daily on the outer ear", correct:true, why:"This is the described non-drug measure; daily outer-canal cleaning with a wrung-out cloth over a finger prevents impaction."},
  {t:"A cotton swab pushed gently into the ear canal each morning and night to lift the wax out", correct:false, why:"Cotton swabs are a listed risk factor for impaction because of improper removal."},
  {t:"A hair dryer on the lowest setting held near the ear", correct:false, why:"The dryer is a way to dry a water-clogged ear, not a way to remove cerumen."}],
 teach:"Daily outer-canal cleaning with a wrung-out cloth over a finger prevents impaction. Swabs raise the risk of impaction, candles are not recommended, and a hair dryer is a drying method for water-clogged ears.",
 cite:"Lecture 13 (Lam_OticDisorders_slides.pdf) slides 13; handout p. 3; T@93959 11/20"},

{id:"LOT-011", skill:"adverse", prof:'Lam', tier:'new', topic:"lt-cerrx", sub:"nonpharm", concept:"lot-tool-risk",
 tags:["hard", "reasoning"], source:"both",
 stem:"A patient plans to remove wax with an ear-cleaning tool (curette) and asks what to watch for. What risk should the pharmacist name?",
 options:[
  {t:"Hot wax dripping onto the skin around the ear opening and burning the outer ear", correct:false, why:"Dripping hot wax is the concern she raised about ear candles, not about a cleaning tool."},
  {t:"Trauma to the canal skin or tympanic membrane if inserted too far", correct:true, why:"The caution is trauma to the canal skin or the eardrum, so the tool must not be pushed deep."},
  {t:"Loss of effect once the tool has been used for more than 4 days in a row", correct:false, why:"A 4-day limit applies to carbamide peroxide drops, not to a manual tool."},
  {t:"Failure to work because the method is not well studied and relies on anecdotal reports", correct:false, why:"The evidence comment she made was about irrigation, not about the cleaning tool."}],
 teach:"An ear-cleaning tool removes wax manually, so the danger is injury: pushing it too far can damage the canal skin or the eardrum. She said to know yourself and the person using it. Candles carry a hot-wax concern, and the evidence caveat belongs to irrigation.",
 cite:"Lecture 13 (Lam_OticDisorders_slides.pdf) slides 13; handout p. 3; T@94016, T@94176 11/20"},

{id:"LOT-012", skill:"counsel", prof:'Lam', tier:'new', topic:"lt-cerrx", sub:"nonpharm", concept:"lot-irrigation",
 tags:["hard", "reasoning"], source:"both",
 stem:"A patient asks why irrigation with warm sterile water and a bulb syringe is on the list of options if it may not work. What did Dr. Lam say?",
 options:[
  {t:"It is the FDA-approved nonprescription product for self-care removal of impacted cerumen", correct:false, why:"The FDA-approved nonprescription product she named is carbamide peroxide, not irrigation."},
  {t:"Controlled trials show it works better than carbamide peroxide for most patients", correct:false, why:"She made no comparison with carbamide peroxide, and she called the evidence weak."},
  {t:"It is required after every dose of carbamide peroxide to clear the loosened wax from the canal", correct:false, why:"Irrigation is optional after drops (drops with or without warm water irrigation)."},
  {t:"It is not well studied, anecdotal reports support it, and it may fail for some", correct:true, why:"She said it is not very well studied; it is in the guidelines because of anecdotal reports, and it may fail."}],
 teach:"Irrigation with warm sterile water and a bulb syringe is included even though it is not well studied: she cited anecdotal success, and her clinic irrigates older adults often. It may not work for every patient. Carbamide peroxide is the product with FDA approval, and irrigation after it is optional.",
 cite:"Lecture 13 (Lam_OticDisorders_slides.pdf) slides 13, 14; handout p. 3; T@94256, T@94327, T@94394 11/20"},

{id:"LOT-013", skill:"class", prof:'Lam', tier:'new', topic:"lt-cerrx", sub:"drug", concept:"lot-product-id",
 tags:["hard", "class"], source:"both",
 stem:"Which is the nonprescription product recommended for removing impacted cerumen?",
 options:[
  {t:"Isopropyl alcohol in anhydrous glycerin, the drying agent for water-clogged ears", correct:false, why:"This is the drying agent for water-clogged ears."},
  {t:"Almond oil or other oil-based drops", correct:false, why:"Oil-based agents are among the other cerumenolytics that are not recommended."},
  {t:"Carbamide peroxide 6.5% in anhydrous glycerin", correct:true, why:"This is Debrox, the FDA-approved nonprescription cerumenolytic that she named as the product to recommend."},
  {t:"Docusate sodium or other water-based drops used as a cerumenolytic", correct:false, why:"Water-based agents such as docusate sodium are not recommended anymore; they are not better than water."}],
 teach:"Carbamide peroxide 6.5% in anhydrous glycerin, sold as Debrox, is the product to recommend for impaction. Water-based and oil-based cerumenolytics are not recommended, and isopropyl alcohol belongs to water-clogged ears.",
 cite:"Lecture 13 (Lam_OticDisorders_slides.pdf) slides 14, 15; handout p. 4; T@94684 11/20"},

{id:"LOT-014", skill:"dose", prof:'Lam', tier:'new', topic:"lt-cerrx", sub:"drug", concept:"lot-cp-directions",
 tags:["hard", "two-facts"], source:"both",
 stem:"Mrs. Okafor, 45, has impacted cerumen with no exclusions and will use carbamide peroxide 6.5%. Which directions are correct?",
 options:[
  {t:"5 to 10 drops in the affected ear, remaining several minutes, once daily for 4 weeks", correct:false, why:"The product is used twice daily for up to 4 days, not for weeks."},
  {t:"4 to 5 drops in the affected ear, remaining several minutes, once daily until clear", correct:false, why:"This sounds like the isopropyl alcohol drops for a water-clogged ear and has no stated end point."},
  {t:"5 to 10 drops in the affected ear, remaining several minutes, twice daily for 7 days", correct:false, why:"The duration is up to 4 days; 7 days is the time she gave for referring a water-clogged ear."},
  {t:"5 to 10 drops in the ear, left several minutes, twice daily for up to 4 days", correct:true, why:"This matches the slide: 5-10 drops, several minutes in the canal, twice daily for up to 4 days."}],
 teach:"Carbamide peroxide is 5 to 10 drops in the affected ear, kept in for several minutes to soften the wax, twice daily for up to 4 days. The 4-to-5-drop dose belongs to the alcohol drops for a water-clogged ear.",
 cite:"Lecture 13 (Lam_OticDisorders_slides.pdf) slides 14, 31; handout p. 4; T@95175, T@95399 11/20"},

{id:"LOT-015", skill:"case", prof:'Lam', tier:'new', topic:"lt-cerrx", sub:"fu", concept:"lot-cp-4days",
 tags:["hard", "case", "reverse"], source:"both",
 stem:"Mr. Ibrahim, 38, used carbamide peroxide drops twice daily for 4 days and still has fullness and itching. What is the appropriate next step?",
 options:[
  {t:"Keep using the drops for another week to finish the course of treatment", correct:false, why:"Use is limited to 4 days; persisting symptoms need a physician."},
  {t:"Contact his PCP because the symptoms persist after 4 days", correct:true, why:"Persistent symptoms after 4 days are the follow-up point; the problem may be an infection, as in her own story."},
  {t:"Switch to isopropyl alcohol drops, 4 to 5 drops, because the wax has not cleared", correct:false, why:"Alcohol drops are for a water-clogged ear, not for persistent impaction."},
  {t:"Use an ear candle to finish removing the wax that the drops loosened", correct:false, why:"Ear candles are not recommended."}],
 teach:"If symptoms persist after 4 days of carbamide peroxide, the patient contacts a physician. She described mistaking an ear infection for earwax and swabbing for 4 days. More drops, a different product or a candle each delay the correct diagnosis.",
 cite:"Lecture 13 (Lam_OticDisorders_slides.pdf) slides 16; handout p. 4; T@96243 11/20"},

{id:"LOT-016", skill:"class", prof:'Lam', tier:'new', topic:"lt-cerrx", sub:"notrec", concept:"lot-not-recommended",
 tags:["hard", "case"], source:"both",
 stem:"A customer asks for almond oil drops and an ear candle to remove wax. How should the pharmacist respond?",
 options:[
  {t:"Neither is recommended; use carbamide peroxide instead", correct:true, why:"Oil- and water-based cerumenolytics are not better than water, and candles are dangerous without evidence."},
  {t:"Almond oil is acceptable as a cerumenolytic, but the candle is not", correct:false, why:"Oil-based agents are on the not-recommended list along with other cerumenolytics."},
  {t:"The candle is acceptable as a gentle option, but almond oil is not", correct:false, why:"Candles are listed as not recommended because of potential danger and injury and no scientific evidence."},
  {t:"Both are acceptable if used twice daily for up to 4 days", correct:false, why:"That schedule belongs to carbamide peroxide; neither product is recommended."}],
 teach:"Other cerumenolytics, water-based or oil-based, are no more effective than water and are not recommended; ear candles are not recommended either (danger and no evidence). Carbamide peroxide is the product to recommend, with irrigation as an optional follow-up.",
 cite:"Lecture 13 (Lam_OticDisorders_slides.pdf) slides 14, 15; handout p. 4; T@95566, T@95719 11/20"},

{id:"LOT-017", skill:"counsel", prof:'Lam', tier:'new', topic:"lt-cerrx", sub:"drug", concept:"lot-cotton-why",
 tags:["hard", "reasoning"], source:"recording",
 stem:"Why might the pharmacist suggest placing a cotton ball in the ear after instilling carbamide peroxide?",
 options:[
  {t:"To dry the canal so the drug can work on the wax that is stuck to the wall", correct:false, why:"Drying is not the aim; the drug is a cerumenolytic that softens wax."},
  {t:"To absorb the loosened wax so that it can be pulled out of the ear afterwards", correct:false, why:"The cotton does not remove wax; irrigation is the removal step."},
  {t:"To hold the drops in the canal long enough to soften wax", correct:true, why:"The drops must remain for a few minutes to soften the wax, and cotton holds them in place."},
  {t:"To replace the warm-water irrigation step afterwards", correct:false, why:"Cotton does not replace irrigation, which clears the loosened wax."}],
 teach:"Carbamide peroxide works by softening the wax, so it has to stay in the canal for several minutes. A cotton ball holds the liquid in place during that time. Removing the loosened wax is a separate step done by gentle warm-water irrigation.",
 cite:"Lecture 13 (Lam_OticDisorders_slides.pdf) slides 14; handout p. 4; T@95175, T@95344 11/20"},

{id:"LOT-018", skill:"counsel", prof:'Lam', tier:'new', topic:"lt-cerrx", sub:"drug", concept:"lot-remaining-wax",
 tags:["hard", "sequence"], source:"both",
 stem:"After carbamide peroxide has softened the wax, how is the remaining cerumen removed?",
 options:[
  {t:"Ear-cleaning tool inserted until the wax comes out of the canal", correct:false, why:"A manual tool carries a risk of trauma and is not the step that follows the drops."},
  {t:"Isopropyl alcohol drops, 4 to 5 drops, followed by a hair dryer", correct:false, why:"Alcohol drops are the drying agent for a water-clogged ear."},
  {t:"Gentle warm-water irrigation with a rubber otic bulb syringe", correct:true, why:"Gentle warm-water irrigation with a rubber otic bulb syringe clears remaining cerumen."},
  {t:"A second round of drops over the next 4 days, with no irrigation", correct:false, why:"Drops are limited to 4 days, and the wax is cleared by irrigation."}],
 teach:"Remaining cerumen is flushed out with gentle warm-water irrigation using a rubber otic bulb syringe; she noted store kits that pair the drops with a bulb. A cleaning tool risks trauma, and alcohol drops treat a different condition.",
 cite:"Lecture 13 (Lam_OticDisorders_slides.pdf) slides 14; handout p. 4; T@95020 11/20"},

{id:"LOT-019", skill:"patho", prof:'Lam', tier:'new', topic:"lt-water", sub:"cause", concept:"lot-wc-causes", multi:true,
 tags:["list", "multi"], source:"both",
 stem:"Which of these can lead to a water-clogged ear? Select all that apply.",
 options:[
  {t:"Excessive hair growth in the ear canal", correct:true, why:"Hair holds moisture and is a listed cause of moisture retention."},
  {t:"Atrophy of the ceruminous glands", correct:false, why:"This is a risk factor for impaction in older adults."},
  {t:"Narrowing of the canal", correct:true, why:"Canal narrowing is a listed cause of moisture retention."},
  {t:"Cough or vertigo", correct:false, why:"These are not listed causes of moisture retention in the canal."},
  {t:"Swimming or heavy sweating", correct:true, why:"Excessive moisture from swimming, sweating or high humidity can become trapped in the ear."}],
 teach:"A water-clogged ear comes from retained moisture (hair, canal narrowing, wax or debris) and from excess moisture (swimming, sweating, humidity). Gland atrophy and genetics are cerumen risk factors. She said the hairs in the ear get fluffy when wet, as scalp hair does.",
 cite:"Lecture 13 (Lam_OticDisorders_slides.pdf) slides 20; handout p. 4; T@96605, T@96941 11/20"},

{id:"LOT-020", skill:"counsel", prof:'Lam', tier:'new', topic:"lt-water", sub:"goal", concept:"lot-goal-wc",
 tags:["hard", "two-facts"], source:"both",
 stem:"Which pair states the treatment goals for a water-clogged ear?",
 options:[
  {t:"Remove the cerumen and prevent potential adverse events from the products used", correct:false, why:"These are the goals for impacted cerumen."},
  {t:"Prevent recurrence and dry the canal safely and effectively", correct:true, why:"These are the stated goals: prevent the problem from recurring and dry the canal safely."},
  {t:"Treat the discharge and reduce the swelling in the canal with a drying agent", correct:false, why:"Discharge and swelling signal infection, which is referred."},
  {t:"Soften the wax and flush the canal with warm water", correct:false, why:"Softening and flushing are steps for impaction."}],
 teach:"For a water-clogged ear, the goals are to prevent recurrence in people prone to retaining moisture and to dry the canal with a safe, effective agent. Removing cerumen and avoiding harm is the impaction goal, so match each goal to its condition.",
 cite:"Lecture 13 (Lam_OticDisorders_slides.pdf) slides 27; handout p. 6; T@98078 11/20"},

{id:"LOT-021", skill:"case", prof:'Lam', tier:'new', topic:"lt-water", sub:"excl", concept:"lot-wc-dizzy",
 tags:["hard", "case"], source:"both",
 stem:"Jamal, 16, swims daily and has ear wetness and fullness for 3 days. He also feels dizzy when he stands. He asks for isopropyl alcohol ear drops. What is the best response?",
 options:[
  {t:"Give isopropyl alcohol drops, 4 to 5 drops in the affected ear", correct:false, why:"Dizziness is on the exclusion list for a water-clogged ear, so drops are not appropriate."},
  {t:"Offer water-absorbing earplugs, since he is older than 11", correct:false, why:"His age fits, but dizziness excludes self-care."},
  {t:"Advise a hair dryer on the lowest setting", correct:false, why:"A drying method is not enough when an exclusion is present."},
  {t:"Refer him to a physician because dizziness is an exclusion", correct:true, why:"Dizziness is listed in the exclusions and in the follow-up signs, so he is referred."}],
 teach:"Dizziness appears on the exclusion list for a water-clogged ear and among the follow-up signs, so the patient goes to a physician even though his age fits the products.",
 cite:"Lecture 13 (Lam_OticDisorders_slides.pdf) slides 26, 34; handout p. 6; T@97876 11/20"},

{id:"LOT-022", skill:"counsel", prof:'Lam', tier:'new', topic:"lt-water", sub:"nonpharm", concept:"lot-wc-nondrug-multi", multi:true,
 tags:["list", "multi"], source:"both",
 stem:"A swimmer is prone to water in her ears. Which non-drug measures apply? Select all that apply.",
 options:[
  {t:"Wipe the ears well with a towel after bathing or showering", correct:true, why:"Towel drying is a listed non-drug measure."},
  {t:"Wear earplugs or a bathing cap when swimming", correct:true, why:"Earplugs or a bathing cap protect the ears from water exposure."},
  {t:"Burn an ear candle to draw out moisture", correct:false, why:"Ear candles are not recommended."},
  {t:"Dry the canal with a blow dryer on the lowest heat setting", correct:true, why:"A blow dryer on the lowest heat setting helps dry the canal."},
  {t:"Wipe the outer canal daily with a wet, wrung-out washcloth", correct:false, why:"This is a non-drug measure for impacted cerumen, not for trapped water."}],
 teach:"Water-clogged ear care is about keeping water out and drying what is there: a towel after bathing, earplugs or a cap when swimming, petroleum-jelly cotton for short exposure, and a dryer on the lowest heat. Candles are not recommended, and the wet washcloth is an impaction measure.",
 cite:"Lecture 13 (Lam_OticDisorders_slides.pdf) slides 29, 30; handout p. 6; T@98127, T@98247, T@98913 11/20"},

{id:"LOT-023", skill:"counsel", prof:'Lam', tier:'new', topic:"lt-water", sub:"nonpharm", concept:"lot-absorbing-age",
 tags:["hard", "case"], source:"both",
 stem:"Which child could be offered water-absorbing earplugs after swimming?",
 options:[
  {t:"A 6-year-old who swims at a pool every week", correct:false, why:"Water-absorbing earplugs are for children older than 11."},
  {t:"A 9-year-old who takes swim lessons twice a week", correct:false, why:"This age is below the cutoff of older than 11."},
  {t:"A 14-year-old who swims on a team", correct:true, why:"This age is above the cutoff for water-absorbing earplugs."},
  {t:"A 3-year-old who splashes in the bath", correct:false, why:"This age is far below the cutoff."}],
 teach:"Water-absorbing earplugs are used in children older than 11 years. Ages 6, 9 and 3 are below that, so those children use other measures such as towel drying. Age 11 itself is printed as older than 11 and spoken as 11 and older.",
 cite:"Lecture 13 (Lam_OticDisorders_slides.pdf) slides 29; handout p. 6; T@98536 11/20"},

{id:"LOT-024", skill:"counsel", prof:'Lam', tier:'new', topic:"lt-water", sub:"nonpharm", concept:"lot-absorbing-time",
 tags:["hard", "number"], source:"both",
 stem:"How long should a water-absorbing earplug stay in the ear canal to absorb trapped water?",
 options:[
  {t:"About 30 to 60 seconds", correct:false, why:"This is too short to absorb trapped water."},
  {t:"About 5 to 10 minutes", correct:true, why:"She said to leave it in for about 5 or 10 minutes; the handout says 5-10 minutes."},
  {t:"About 20 to 30 minutes, then discard it", correct:false, why:"This is longer than the stated time."},
  {t:"Overnight, removed in the morning", correct:false, why:"Overnight use is not described; the plug is removed and discarded after 5-10 minutes."}],
 teach:"A water-absorbing earplug is inserted into the canal, left for 5 to 10 minutes to absorb trapped water, then removed and discarded. It absorbs a small amount of water, she noted. It is not worn through the night.",
 cite:"Lecture 13 (Lam_OticDisorders_slides.pdf) slides 29, 30; handout p. 6; T@98686 11/20"},

{id:"LOT-025", skill:"tell", prof:'Lam', tier:'new', topic:"lt-water", sub:"nonpharm", concept:"lot-absorb-vs-plug",
 tags:["hard", "tell"], source:"slide",
 stem:"A patient asks whether a water-absorbing earplug will keep water out while he swims. What is the correct answer?",
 options:[
  {t:"Yes, it seals the ear canal and blocks water during swimming or bathing", correct:false, why:"Sealing the canal is the job of regular earplugs or a bathing cap."},
  {t:"No, it absorbs trapped water but does not stop water entering", correct:true, why:"The handout states it will not prevent water entering; it removes trapped water."},
  {t:"Yes, once the plug has been coated with petroleum jelly before swimming", correct:false, why:"Petroleum-jelly cotton is a separate measure for short exposure."},
  {t:"No, because it works by drying the canal with isopropyl alcohol drops", correct:false, why:"It contains no alcohol; it absorbs water."}],
 teach:"A water-absorbing earplug treats water already in the canal; it does not prevent water from entering during bathing or swimming. For prevention, use regular earplugs or a bathing cap.",
 cite:"Lecture 13 (Lam_OticDisorders_slides.pdf) slides 29, 30; handout p. 6"},

{id:"LOT-026", skill:"class", prof:'Lam', tier:'new', topic:"lt-water", sub:"drug", concept:"lot-alcohol-id",
 tags:["hard", "class"], source:"both",
 stem:"Which nonprescription product is used to dry a water-clogged ear?",
 options:[
  {t:"Carbamide peroxide 6.5% in anhydrous glycerin", correct:false, why:"This softens wax in impaction and is not a drying agent."},
  {t:"Isopropyl alcohol in anhydrous glycerin", correct:true, why:"Isopropyl alcohol is the drying agent; she called it the one product."},
  {t:"Choline salicylate drops, a water-based cerumenolytic", correct:false, why:"A water-based cerumenolytic that is not recommended."},
  {t:"A cotton ball coated with petroleum jelly, used to keep water out", correct:false, why:"This is a non-drug measure to keep water out, not a drying drug."}],
 teach:"Isopropyl alcohol is the drying agent for a water-clogged ear. It is the one product she named for it, while carbamide peroxide is the one for impaction. The concentration is printed as 95% in 5% glycerin and spoken as 70%.",
 cite:"Lecture 13 (Lam_OticDisorders_slides.pdf) slides 31; handout p. 6; T@99198 11/20"},

{id:"LOT-027", skill:"mech", prof:'Lam', tier:'new', topic:"lt-water", sub:"drug", concept:"lot-alcohol-mech",
 tags:["hard", "mech"], source:"both",
 stem:"How does isopropyl alcohol help a water-clogged ear?",
 options:[
  {t:"It softens hardened wax so that it can be irrigated", correct:false, why:"This is the action of carbamide peroxide in impaction."},
  {t:"It acts as a drying agent that helps dry the canal", correct:true, why:"The handout calls alcohol a drying agent used to dry the canal."},
  {t:"It absorbs trapped water into a plug and is then discarded", correct:false, why:"This describes a water-absorbing earplug."},
  {t:"It kills the infection that traps water in the canal", correct:false, why:"Infection is not treated with OTC otic products."}],
 teach:"Isopropyl alcohol dries the ear canal, so it clears water that is trapped there. Softening wax belongs to carbamide peroxide, and absorbing water into a plug belongs to the earplug. Infection needs a physician.",
 cite:"Lecture 13 (Lam_OticDisorders_slides.pdf) slides 31; handout p. 6; T@99198 11/20"},

{id:"LOT-028", skill:"dose", prof:'Lam', tier:'new', topic:"lt-water", sub:"drug", concept:"lot-two-patients",
 tags:["hard", "reverse", "two-facts"], source:"both",
 stem:"A pharmacist writes counseling notes for two patients: one with impacted cerumen and one with a water-clogged ear. Which line belongs to the patient with the water-clogged ear?",
 options:[
  {t:"Instill 5 to 10 drops twice daily for up to 4 days", correct:false, why:"This is the carbamide peroxide schedule for impaction."},
  {t:"Follow the drops with gentle warm-water irrigation using a bulb syringe", correct:false, why:"Irrigation follows carbamide peroxide in impaction."},
  {t:"Contact your PCP if symptoms persist after 4 days", correct:false, why:"This is the follow-up point for impaction."},
  {t:"Instill 4 to 5 drops in the affected ear", correct:true, why:"This is the dose given for isopropyl alcohol on the water-clogged ear slide."}],
 teach:"Each condition has its own product and instructions: impaction uses 5 to 10 drops twice daily for up to 4 days, then irrigation, and a call to the PCP after 4 days. The water-clogged ear uses 4 to 5 drops of the drying agent.",
 cite:"Lecture 13 (Lam_OticDisorders_slides.pdf) slides 14, 16, 31; handout p. 4, 6; T@99431 11/20"},

{id:"LOT-029", skill:"counsel", prof:'Lam', lowYield:true, tier:'new', topic:"lt-water", sub:"drug", concept:"lot-no-min-age",
 tags:["hard", "reasoning"], source:"both",
 stem:"What is the minimum age for isopropyl alcohol drops for a water-clogged ear?",
 options:[
  {t:"There is no minimum age for the alcohol drops", correct:true, why:"Slide 31 and her speech say there is no minimum age."},
  {t:"A minimum age of 2 years, below which she refers", correct:false, why:"No age of 2 years is stated."},
  {t:"Older than 11 years, the same cutoff as the earplugs", correct:false, why:"This is the age cutoff for water-absorbing earplugs."},
  {t:"12 years or older, the cutoff for treating impacted cerumen", correct:false, why:"This is the cutoff she used for treating impacted cerumen."}],
 teach:"The alcohol drops carry no minimum age on slide 31, and she repeated it; but the exclusion list on slide 26 includes age under 12. The two statements conflict. Earplugs use older than 11, and the cerumen product uses 12 or older.",
 note:"Slide 31 and she say no minimum age, but the exclusion list on slide 26 (and the handout) lists age under 12; the conflict is not resolved.",
 cite:"Lecture 13 (Lam_OticDisorders_slides.pdf) slides 26, 31; handout p. 6; T@99389 11/20"},

{id:"LOT-030", skill:"tell", prof:'Lam', tier:'new', topic:"lt-diff", sub:"three", concept:"lot-itch-split",
 tags:["hard", "tell"], source:"both",
 stem:"Which feature separates a water-clogged ear from impacted cerumen?",
 options:[
  {t:"Water-clogged: no itching; cerumen impaction: often itching", correct:true, why:"She underlined it: a water-clogged ear has no pain and no itching, and wax gives itching."},
  {t:"Water-clogged: loss of hearing is absent; cerumen impaction: often present", correct:false, why:"Hearing loss is often present in both."},
  {t:"Water-clogged: clear discharge; cerumen impaction: no discharge", correct:false, why:"Neither has discharge; clear discharge points to swimmer's ear."},
  {t:"Water-clogged: acute pain; cerumen impaction: no pain", correct:false, why:"Acute pain points to swimmer's ear; cerumen has rare, dull pain at most."}],
 teach:"Hearing loss and a sense of fullness appear in both, so the difference is itching: a water-clogged ear does not itch and has no pain, while wax often itches. Discharge or acute pain moves the answer to swimmer's ear, which is referred.",
 cite:"Lecture 13 (Lam_OticDisorders_slides.pdf) slides 23; T@97351, T@97500 11/20"},

{id:"LOT-031", skill:"case", prof:'Lam', tier:'new', topic:"lt-diff", sub:"three", concept:"lot-case-wc",
 tags:["hard", "case"], source:"both",
 stem:"Mr. Dunn, 30, swims laps most days. His left ear feels full and wet and sounds muffled. He has no pain, itching or discharge. Which is the most likely diagnosis?",
 options:[
  {t:"Water-clogged ear", correct:true, why:"Fullness or wetness with hearing loss, no pain, no itching and no discharge matches a water-clogged ear."},
  {t:"Impacted cerumen", correct:false, why:"Impaction usually itches and may have dull pain."},
  {t:"Swimmer's ear (external otitis)", correct:false, why:"Swimmer's ear has acute pain, itching and clear discharge."},
  {t:"Otitis media", correct:false, why:"Otitis media has sharp, steady, unilateral pain and a bulging eardrum."}],
 teach:"The table row for a water-clogged ear is no pain, no itching, hearing loss often, no discharge and a sense of fullness or wetness. Swimmers are exposed to water constantly. Add itching and impaction fits; add pain and clear discharge and it is swimmer's ear.",
 cite:"Lecture 13 (Lam_OticDisorders_slides.pdf) slides 21, 23; T@97351 11/20"},

{id:"LOT-032", skill:"case", prof:'Lam', tier:'new', topic:"lt-diff", sub:"three", concept:"lot-case-cer",
 tags:["hard", "case"], source:"both",
 stem:"Ms. Reyes, 68, wears hearing aids. She has ear itching, a sense of pressure and muffled hearing for 5 days. She has no pain or discharge. Which is the most likely diagnosis?",
 options:[
  {t:"Water-clogged ear", correct:false, why:"A water-clogged ear does not itch."},
  {t:"Swimmer's ear (external otitis)", correct:false, why:"Swimmer's ear has acute pain and clear discharge."},
  {t:"Ruptured tympanic membrane", correct:false, why:"A rupture brings abrupt hearing loss with brief, severe pain."},
  {t:"Impacted cerumen", correct:true, why:"Itching, pressure and hearing loss with no discharge and hearing aids as a risk factor fit impaction."}],
 teach:"Itching with a sense of pressure and hearing loss, no discharge, in a hearing-aid user points to impacted cerumen. A water-clogged ear would not itch, swimmer's ear would show acute pain and clear discharge, and a rupture is abrupt and sharp.",
 cite:"Lecture 13 (Lam_OticDisorders_slides.pdf) slides 8, 23, 24; T@97500 11/20"},

{id:"LOT-033", skill:"case", prof:'Lam', tier:'new', topic:"lt-diff", sub:"three", concept:"lot-case-swimmer",
 tags:["hard", "case"], source:"both",
 stem:"Tyler, 9, has had ear pain that started suddenly yesterday, itching and clear fluid draining from the ear. His ear canal looks swollen and his temperature is 101 F. What should the pharmacist do?",
 options:[
  {t:"Recommend isopropyl alcohol drops, 4 to 5 drops", correct:false, why:"Alcohol drops are excluded with discharge, and this is an infection."},
  {t:"Recommend carbamide peroxide 6.5% twice daily for up to 4 days to clear the canal", correct:false, why:"This is for impaction, and the child is under 12 with signs of infection."},
  {t:"Offer water-absorbing earplugs and a towel to keep water out of the ear", correct:false, why:"Prevention measures do not treat an infection."},
  {t:"Refer him to a physician; this is swimmer's ear, an infection", correct:true, why:"Acute pain, itching, clear discharge, a swollen canal and fever fit swimmer's ear, which has no OTC treatment."}],
 teach:"Acute pain, itching, clear discharge, a swollen canal and fever fit swimmer's ear (external otitis). It is an infection, so the pharmacist refers; no OTC product treats it, and he is under 12 as well.",
 cite:"Lecture 13 (Lam_OticDisorders_slides.pdf) slides 23, 26; T@93213, T@97615 11/20"},

{id:"LOT-034", skill:"tell", prof:'Lam', tier:'new', topic:"lt-diff", sub:"three", concept:"lot-swimmer-multi", multi:true,
 tags:["list", "multi"], source:"both",
 stem:"Which findings point to swimmer's ear rather than a water-clogged ear? Select all that apply.",
 options:[
  {t:"Acute onset of ear pain", correct:true, why:"Acute onset pain, mild to severe, is part of external otitis."},
  {t:"A sense of fullness or wetness with no pain", correct:false, why:"This is the water-clogged pattern."},
  {t:"Clear ear discharge", correct:true, why:"Clear discharge is a swimmer's ear finding; a water-clogged ear has none."},
  {t:"No itching", correct:false, why:"A water-clogged ear has no itching; swimmer's ear itches."},
  {t:"Fever and swollen lymph nodes", correct:true, why:"Fever and swollen lymph nodes are listed with external otitis."}],
 teach:"Swimmer's ear is an infection: acute pain, itching, clear discharge, a swollen canal, fever and swollen lymph nodes. A water-clogged ear has no pain, no itching and no discharge. A patient with the infection pattern is referred.",
 cite:"Lecture 13 (Lam_OticDisorders_slides.pdf) slides 23; T@97615, T@97716 11/20"},

{id:"LOT-035", skill:"counsel", prof:'Lam', tier:'new', topic:"lt-diff", sub:"three", concept:"lot-cannot-treat",
 tags:["hard", "tell"], source:"both",
 stem:"Of water-clogged ear, impacted cerumen and swimmer's ear, which condition does the pharmacist refer rather than treat?",
 options:[
  {t:"Water-clogged ear", correct:false, why:"It can be treated with a drying agent and non-drug measures when no exclusion is present."},
  {t:"Impacted cerumen", correct:false, why:"It can be treated with carbamide peroxide when no exclusion is present."},
  {t:"Swimmer's ear", correct:true, why:"It is an infection, and she said there is nothing to treat an infection with at the pharmacy."},
  {t:"All three can be treated with the same OTC product", correct:false, why:"Each condition has a different product or is referred."}],
 teach:"Swimmer's ear is an infection and is referred to a physician. Wax and water in the ear have OTC options, as long as no exclusion such as discharge, pain with discharge, tubes or recent surgery is present.",
 cite:"Lecture 13 (Lam_OticDisorders_slides.pdf) slides 23; T@93008, T@97615 11/20"},

{id:"LOT-036", skill:"tell", prof:'Lam', lowYield:true, tier:'new', topic:"lt-diff", sub:"others", concept:"lot-ruptured-tm",
 tags:["hard", "tell"], source:"both",
 stem:"A patient has abrupt hearing loss after a sudden, brief, severe ear pain and no itching. Which condition does this pattern fit?",
 options:[
  {t:"Impacted cerumen with itching", correct:false, why:"Impaction has rare, dull pain and often itching."},
  {t:"Ruptured tympanic membrane", correct:true, why:"The table lists brief, severe pain, no itching and abrupt hearing loss."},
  {t:"Water-clogged ear with fullness", correct:false, why:"A water-clogged ear has no pain."},
  {t:"Otitis media with a bulging eardrum", correct:false, why:"Otitis media has sharp, steady, unilateral pain and a decrease in hearing sometimes."}],
 teach:"A ruptured tympanic membrane brings brief, severe pain and abrupt hearing loss, and it is an exclusion to self-care. She said the main slide to know is the three-way comparison, so this row is a lower-priority recognition item.",
 note:"Slide 24 rows are lower priority: she said the main slide is 23 (T@97767).",
 cite:"Lecture 13 (Lam_OticDisorders_slides.pdf) slides 24; handout p. 5; T@97767 11/20"},

{id:"LOT-037", skill:"counsel", lowYield:true, prof:'Lam', tier:'new', topic:"lt-impl", sub:"drops", concept:"lot-adult-position",
 tags:["hard", "counsel"], source:"slide",
 stem:"Which technique should an adult use to instill ear drops?",
 options:[
  {t:"Sit upright with the affected ear down, pull the earlobe down gently, and instill the drops", correct:false, why:"Gravity should carry the drops into the canal, so the affected ear faces up."},
  {t:"Lie with the ear up, pull the lobe out and up, instill, and stay there", correct:true, why:"Lying with the ear up and pulling the lobe out and up straightens the canal for the drops."},
  {t:"Lie with the affected ear up and pull the ear back and down gently, then instill the drops", correct:false, why:"Back and down is the technique for children younger than 3."},
  {t:"Stand with the head tilted, instill the drops and rise right away", correct:false, why:"Staying in position for a few minutes keeps the drops in the canal."}],
 teach:"For an adult, lie with the affected ear up, pull the earlobe out and up to straighten the canal, instill the drops and stay in place. Pulling the ear back and down is the child's technique for age under 3.",
 cite:"Lecture 13 (Lam_OticDisorders_slides.pdf) slides 33; handout p. 7; T@99534 11/20"},

{id:"LOT-038", skill:"counsel", lowYield:true, prof:'Lam', tier:'new', topic:"lt-impl", sub:"drops", concept:"lot-child-position",
 tags:["hard", "case"], source:"both",
 stem:"A physician has prescribed ear drops for a 2-year-old. How should the pharmacist tell the parent to position the ear?",
 options:[
  {t:"Pull the earlobe out and up, with the affected ear up, as for an adult", correct:false, why:"This is the adult technique."},
  {t:"Pull the ear back and down, with the affected ear up", correct:true, why:"For children younger than 3, pull the ear back and down."},
  {t:"Hold the child upright and pull the earlobe up and out gently", correct:false, why:"The child lies with the affected ear up."},
  {t:"Pull the ear back and down with the affected ear down toward the floor", correct:false, why:"The affected ear is up so the drops run in."}],
 teach:"For a child under 3, the child lies with the affected ear up and the ear is pulled back and down. The adult technique pulls the lobe out and up. Keeping the child still afterwards, even with a video, helps the drops stay in the canal.",
 cite:"Lecture 13 (Lam_OticDisorders_slides.pdf) slides 33; handout p. 7; T@99685 11/20"},

{id:"LOT-039", skill:"counsel", lowYield:true, prof:'Lam', tier:'new', topic:"lt-impl", sub:"drops", concept:"lot-child-cotton",
 tags:["hard", "counsel"], source:"both",
 stem:"A child will not stay still after drops. If a parent places cotton in the ear to keep the solution in, which advice is correct?",
 options:[
  {t:"Leave the cotton in overnight so that the drops stay in until morning", correct:false, why:"The limit is 1 hour."},
  {t:"Push the cotton deeply into the canal so the drops cannot escape or leak out", correct:false, why:"Cotton large enough to remove easily is used; a deep plug cannot be removed safely."},
  {t:"Use a cotton swab to push the drops further into the canal and hold them there", correct:false, why:"Swabs are a risk factor for impaction and are the wrong tool."},
  {t:"Use clean cotton big enough to remove easily, for up to 1 hour", correct:true, why:"The handout says clean cotton large enough to remove easily, for no longer than 1 hour."}],
 teach:"If a child will not stay still, a clean piece of cotton large enough to remove easily may hold the drops in, for no longer than 1 hour. She joked that no child likes it, so holding the child still while watching TV for a few minutes is the first choice.",
 cite:"Lecture 13 (Lam_OticDisorders_slides.pdf) slides 33; handout p. 7; T@99685 11/20"},

{id:"LOT-040", skill:"case", prof:'Lam', tier:'new', topic:"lt-impl", sub:"fu", concept:"lot-wc-7days",
 tags:["hard", "case"], source:"both",
 stem:"Ms. Cohen, 28, has used isopropyl alcohol ear drops for 7 days for a water-clogged ear and notices no benefit. What should the pharmacist advise?",
 options:[
  {t:"Keep using the drops for another 7 days to finish the treatment", correct:false, why:"Use beyond 7 days without benefit is not advised."},
  {t:"Switch to carbamide peroxide 6.5% twice daily for up to 4 days", correct:false, why:"Carbamide peroxide is for impacted cerumen."},
  {t:"See her PCP, since there is no benefit after 7 days", correct:true, why:"No benefit after 7 days of use is the follow-up point, so she is referred."},
  {t:"Burn an ear candle to finish drying the canal", correct:false, why:"Ear candles are not recommended."}],
 teach:"No benefit after 7 days of use means a visit to the PCP. Switching to another product or repeating the same one delays a diagnosis, and candles are not recommended. The printed follow-up reads several days; she said 7.",
 cite:"Lecture 13 (Lam_OticDisorders_slides.pdf) slides 34; handout p. 7; T@100232 11/20"},

{id:"LOT-041", skill:"counsel", prof:'Lam', tier:'new', topic:"lt-impl", sub:"fu", concept:"lot-wc-refer-multi", multi:true,
 tags:["list", "multi"], source:"both",
 stem:"A patient is using isopropyl alcohol ear drops. Which events call for referral? Select all that apply.",
 options:[
  {t:"Ear discharge", correct:true, why:"Ear drainage or discharge is a referral sign."},
  {t:"Pain, burning or irritation after using the drops", correct:true, why:"Pain, burning or irritation with the medication is a referral sign."},
  {t:"Mild improvement in hearing after 2 days", correct:false, why:"Improvement is the expected response, not a reason to refer."},
  {t:"Dizziness", correct:true, why:"Dizziness is a referral sign and an exclusion."},
  {t:"Recent ear surgery", correct:true, why:"Recent ear surgery is a referral sign."}],
 teach:"Refer if the ear starts draining, if the drops cause pain, burning or irritation, if dizziness develops, if there was recent ear surgery or if there is no benefit after the stated time. Improvement is the goal and needs no action.",
 cite:"Lecture 13 (Lam_OticDisorders_slides.pdf) slides 34; handout p. 7; T@100297 11/20"},

{id:"LOT-042", skill:"case", prof:'Lam', lowYield:true, tier:'new', topic:"lt-cer", sub:"excl", concept:"lot-age-12",
 tags:["hard", "case"], source:"both",
 stem:"Priya, 12, has ear fullness and itching from wax, with no discharge, pain, tubes or surgery. A parent asks for carbamide peroxide. According to slide 10 and the handout, what is the answer?",
 options:[
  {t:"Refer: children 12 years or under are not treated, as she said in class", correct:false, why:"She said she does not treat children 12 years or under."},
  {t:"Treat: slide excludes under 12 and handout says 12 and older", correct:true, why:"The slide lists less than 12 years as an exclusion and the handout gives 12 years and older."},
  {t:"Treat: there is no age limit for carbamide peroxide in impacted cerumen", correct:false, why:"An age limit is listed."},
  {t:"Refer: ear fullness with itching is an infection until proven otherwise", correct:false, why:"Fullness and itching are the usual presentation of impaction."}],
 teach:"The slide (under 12) and the handout (12 and older) include a 12-year-old; her spoken '12 years or under' excludes one. The two cannot be reconciled for a 12-year-old; ages 8 and 40 are clear.",
 note:"Slide 10 and the handout (<12 excluded; 12 and older) disagree with her speech ('12 years or under', T@93276) about age 12.",
 cite:"Lecture 13 (Lam_OticDisorders_slides.pdf) slides 10, 14; handout p. 3; T@93389 11/20"},

{id:"LOT-043", skill:"case", prof:'Lam', tier:'new', topic:"lt-case", sub:"c1", concept:"lot-c1-candidate",
 tags:["case"], source:"slide",
 stem:"A mother and her 12-year-old daughter come to the pharmacy. The daughter reports wetness, fullness and ear discharge that began after swimming lessons. She had tympanostomy tubes in her ears at age 4. Is she a candidate for self-care, and why?",
 options:[
  {t:"Yes, because wetness and fullness after swimming are a water-clogged ear", correct:false, why:"The ear discharge and the tube history point away from a simple water-clogged ear."},
  {t:"Yes, because she is 12 and has no allergies", correct:false, why:"Age does not decide this case; the findings do."},
  {t:"No, because ear discharge and tympanostomy tubes exclude self-care", correct:true, why:"Ear discharge is a sign of infection and tubes exclude self-care, so she needs a physician."},
  {t:"No, because swimming is a risk factor for impacted cerumen", correct:false, why:"Swimming is a cause of trapped water, not a reason for exclusion or a cerumen risk factor."}],
 teach:"Discharge suggests infection, and tympanostomy tubes are on the exclusion lists for both conditions. Wetness and fullness after swimming alone would suggest a water-clogged ear, but the discharge and the tube history take her out of self-care.",
 cite:"Lecture 13 (Lam_OticDisorders_slides.pdf) slides 36, 37; handout p. 8; T@100668 11/20"},

{id:"LOT-044", skill:"case", prof:'Lam', tier:'new', topic:"lt-case", sub:"c1", concept:"lot-c1-intervention",
 tags:["case", "recall"], source:"slide",
 stem:"A mother and her 12-year-old daughter come to the pharmacy. The daughter reports wetness, fullness and ear discharge that began after her swimming lessons. She had tympanostomy tubes in her ears when she was four years old. Select the most appropriate intervention.",
 options:[
  {t:"Isopropyl alcohol 95% in anhydrous glycerin 5%", correct:false, why:"Alcohol drops are the drying agent for a water-clogged ear, but discharge excludes self-care."},
  {t:"Water-absorbing single-use ear plugs to remove water after swimming", correct:false, why:"Earplugs do not address discharge and are not the answer."},
  {t:"Carbamide peroxide 6.5%", correct:false, why:"This is for impacted cerumen, not for wetness and discharge."},
  {t:"The mother should contact the pediatrician immediately.", correct:true, why:"Discharge and a tube history mean the patient is referred."}],
 teach:"The right step is the referral, since ear discharge and tympanostomy tubes exclude self-care. The three products treat wax or trapped water; none is appropriate because discharge and tubes exclude self-care.",
 cite:"Lecture 13 (Lam_OticDisorders_slides.pdf) slides 37; handout p. 8; T@100668 11/20"},

{id:"LOT-045", skill:"case", prof:'Lam', tier:'new', topic:"lt-case", sub:"c1", concept:"lot-c1-new",
 tags:["hard", "case", "reverse"], source:"both",
 stem:"Nia, 15, has had a sense of fullness and wetness in her right ear since swim practice. She has no pain, itching, discharge, dizziness or surgery history. Which recommendation is most appropriate?",
 options:[
  {t:"Refer her to the pediatrician immediately because she is a minor with ear symptoms", correct:false, why:"Age 15 is not an exclusion, and she has no exclusion finding."},
  {t:"Carbamide peroxide 6.5%, 5 to 10 drops twice daily for 4 days, then irrigate", correct:false, why:"This is for impacted cerumen; her pattern is a water-clogged ear."},
  {t:"An ear candle placed at the ear opening to draw the water out of the canal", correct:false, why:"Ear candles are not recommended."},
  {t:"Towel-dry, then isopropyl alcohol drying drops, 4 to 5 drops", correct:true, why:"Her findings fit a water-clogged ear without exclusions; a towel and the drying agent are appropriate."}],
 teach:"Fullness or wetness with no pain, itching or discharge and no exclusion is a water-clogged ear; the drying agent is 4 to 5 drops, with towel drying, earplugs or a dryer on the lowest heat.",
 cite:"Lecture 13 (Lam_OticDisorders_slides.pdf) slides 23, 31; T@97351, T@99431 11/20"},

{id:"LOT-046", skill:"case", prof:'Lam', tier:'new', topic:"lt-case", sub:"c2", concept:"lot-c2-type",
 tags:["case", "recall"], source:"slide",
 stem:"A 72-year-old patient presents to the pharmacy complaining of fullness in their left ear, itchiness, and dull pain for the past week. The patient reports that they tried using a cotton swab to clean the ear, but it did not help. They denied signs of infection or trauma. What type of otic disorder is this patient experiencing?",
 options:[
  {t:"Water-clogged ear", correct:false, why:"A water-clogged ear has no itching and no pain."},
  {t:"External otitis", correct:false, why:"External otitis has acute pain and clear discharge, which are absent."},
  {t:"Cerumen impaction", correct:true, why:"Itching, fullness and rare dull pain with no discharge fit impaction, and age and swabbing are risk factors."},
  {t:"Ruptured tympanic membrane", correct:false, why:"A rupture brings abrupt hearing loss and brief, severe pain."}],
 teach:"This is her practice case as printed. Fullness, itching and dull pain without discharge, in an older adult who uses swabs, is cerumen impaction. The handout version of the case describes slow hearing loss in place of dull pain, and the answer is the same.",
 cite:"Lecture 13 (Lam_OticDisorders_slides.pdf) slides 39; handout p. 8; T@100668 11/20"},

{id:"LOT-047", skill:"case", prof:'Lam', tier:'new', topic:"lt-case", sub:"c2", concept:"lot-c2-candidate",
 tags:["hard", "case"], source:"slide",
 stem:"A 72-year-old patient reports fullness and itching in the left ear for a week. A cotton swab did not help. There are no signs of infection or trauma. Is the patient a candidate for self-care, and why?",
 options:[
  {t:"Yes, because no exclusion applies and there are no infection signs", correct:true, why:"No exclusion is present; the findings fit impaction that can be treated."},
  {t:"No, because older adults are excluded from self-care with ear symptoms", correct:false, why:"Older age is a risk factor for impaction, not an exclusion."},
  {t:"No, because a cotton swab was already tried without any benefit", correct:false, why:"Failure of a swab is not an exclusion; the exclusion is worsening after self-treatment."},
  {t:"No, because dull pain in the ear means an infection is present", correct:false, why:"Dull pain can occur with cerumen, and pain with discharge is the infection sign."}],
 teach:"The exclusion list covers infection signs, trauma, a ruptured eardrum, tubes, recent surgery, age under 12 and worsening after self-treatment. None applies to this patient, so impaction can be treated. Older age is a risk factor, not an exclusion.",
 cite:"Lecture 13 (Lam_OticDisorders_slides.pdf) slides 41; handout p. 9; T@100668 11/20"},

{id:"LOT-048", skill:"case", prof:'Lam', tier:'new', topic:"lt-case", sub:"c2", concept:"lot-c2-rec",
 tags:["case", "recall"], source:"slide",
 stem:"A 72-year-old patient has fullness and itching in the left ear for a week. A cotton swab did not help. There are no signs of infection or trauma. What is the best recommendation?",
 options:[
  {t:"Carbamide peroxide 6.5%", correct:true, why:"This is the nonprescription cerumenolytic for impaction without exclusions."},
  {t:"Isopropyl alcohol 95% in anhydrous glycerin 5%", correct:false, why:"This is the drying agent for a water-clogged ear."},
  {t:"Ear candles", correct:false, why:"Ear candles are not recommended."},
  {t:"Seek treatment from the PCP", correct:false, why:"Referral is not needed without an exclusion; the PCP is for persistence after 4 days."}],
 teach:"Impaction without exclusions is treated with carbamide peroxide 6.5%. The alcohol is for trapped water, candles are not recommended, and the PCP is the next step when symptoms persist after 4 days. These are her options for question 5.",
 cite:"Lecture 13 (Lam_OticDisorders_slides.pdf) slides 42; handout p. 9; T@94684, T@100668 11/20"},

{id:"LOT-049", skill:"counsel", prof:'Lam', tier:'new', topic:"lt-case", sub:"c2", concept:"lot-c2-counsel", multi:true,
 tags:["hard", "multi", "counsel"], source:"both",
 stem:"A 72-year-old is starting carbamide peroxide 6.5% ear drops. Which counseling points are correct? Select all that apply.",
 options:[
  {t:"Instill 5 to 10 drops into the affected ear", correct:true, why:"The dose is 5 to 10 drops into the affected ear."},
  {t:"Keep the drops in the canal for several minutes; a cotton ball may help hold them in", correct:true, why:"The drops must stay in for several minutes to soften the wax."},
  {t:"Use the drops twice daily for up to 4 days", correct:true, why:"The schedule is twice daily for up to 4 days."},
  {t:"Use the drops for 7 days, then see the PCP", correct:false, why:"The limit is up to 4 days; 7 days is the water-clogged ear time."},
  {t:"Remove the remaining wax with gentle warm-water irrigation using a rubber bulb syringe", correct:true, why:"Remaining cerumen is removed with gentle warm-water irrigation."}],
 teach:"This is her counseling task (question 6). The points are the dose (5 to 10 drops), the time in the canal (several minutes, cotton may help), the schedule (twice daily for up to 4 days), irrigation for leftover wax and a call to the PCP if symptoms persist after 4 days.",
 cite:"Lecture 13 (Lam_OticDisorders_slides.pdf) slides 14, 16, 44; handout p. 9; T@95175, T@95344, T@95399, T@96243 11/20"},

{id:"LOT-050", skill:"case", prof:'Lam', tier:'new', topic:"lt-case", sub:"c3", concept:"lot-c3-hearingaid",
 tags:["hard", "case", "two-facts"], source:"both",
 stem:"Mr. Weiss, 67, wears hearing aids and has ear itching, pressure and ringing for 6 days. He has no pain, discharge, dizziness or surgery history. He used cotton swabs daily and asks what to do. Which plan is most appropriate?",
 options:[
  {t:"Refer immediately because ringing alone excludes him; no product or follow-up plan needed", correct:false, why:"Ringing with no discharge, dizziness or surgery history is not on the exclusion list; the plan is to stop swabs and treat."},
  {t:"Stop swabs; isopropyl alcohol 4 to 5 drops; PCP if no benefit after 7 days", correct:false, why:"This is the water-clogged ear plan."},
  {t:"Keep the swabs; almond oil drops twice daily; PCP if no relief after 4 days", correct:false, why:"Swabs are a risk factor and oil-based agents are not recommended."},
  {t:"Stop swabs; carbamide peroxide 6.5% twice daily up to 4 days; PCP if no relief", correct:true, why:"This plan covers the product, the schedule and the follow-up for impaction."}],
 teach:"Itching, pressure and ringing with hearing aids and no exclusion is impacted cerumen. The plan is to stop swabs, use carbamide peroxide for up to 4 days and refer if symptoms persist. The alcohol plan uses a 7-day follow-up.",
 cite:"Lecture 13 (Lam_OticDisorders_slides.pdf) slides 8, 14, 16; T@92615, T@95175, T@96243 11/20"}
);
